final binding = GestureBinding.instance;
final start = ro.localToGlobal(ro.size.center(Offset.zero));

Map<String, Object?>? duringSnapshot;
Future<void> maybeSnapshot(int step) async {
  if (!shouldSnapshotDuringDrag || snapshotStep != step) return;
  final renderObject = DebugHooks.screenshotBoundaryKey.currentContext
      ?.findRenderObject();
  if (renderObject is! RenderRepaintBoundary) {
    throw StateError('screenshot boundary not mounted yet');
  }
  final image = await renderObject.toImage(
    pixelRatio: snapshotPixelRatio,
  );
  final png = await image.toByteData(format: ui.ImageByteFormat.png);
  final width = image.width;
  final height = image.height;
  image.dispose();
  if (png == null) {
    throw StateError('toByteData returned null');
  }
  duringSnapshot = {
    'png_base64': base64Encode(png.buffer.asUint8List()),
    'width': width,
    'height': height,
    'step': step,
  };
}

